// ByteForge .bfng v1 reader/generator; Rust standard library only.
use std::{env,fs,process};
#[derive(Clone)] struct Edge{ctx:Vec<usize>,next:usize,count:u64}
fn die(s:&str)->!{eprintln!("byteforge: {s}");process::exit(1)}
fn hex(s:&str)->Vec<u8>{if s.len()%2!=0{die("odd token hex")};(0..s.len()).step_by(2).map(|i|u8::from_str_radix(&s[i..i+2],16).unwrap_or_else(|_|die("bad token hex"))).collect()}
fn main(){let a:Vec<String>=env::args().collect();if a.len()<2||a.len()>3{die("usage: byteforge model.bfng [token-count]")};let data=fs::read_to_string(&a[1]).unwrap_or_else(|_|die("cannot read model"));let mut lines=data.lines();let h:Vec<&str>=lines.next().unwrap_or("").split('\t').collect();if h.len()!=4||h[0]!="BYTEFORGE_NGRAM_V1"{die("bad model header")};let order=h[1].parse::<usize>().unwrap_or(0);let vn=h[2].parse::<usize>().unwrap_or(0);let bos=h[3].parse::<usize>().unwrap_or(usize::MAX);if !(1..=8).contains(&order)||vn==0||vn>20000||bos!=vn{die("invalid model header")};let mut vocab=vec![None;vn];let mut edges=Vec::new();for line in lines{let p:Vec<&str>=line.split('\t').collect();if p.len()==3&&p[0]=="v"{let i=p[1].parse::<usize>().unwrap_or(vn);if i>=vn{die("vocab id out of bounds")};vocab[i]=Some(String::from_utf8(hex(p[2])).unwrap_or_else(|_|die("invalid token utf8")));}else if p.len()==order+3&&p[0]=="n"{let ctx:Vec<usize>=p[1..=order].iter().map(|x|x.parse().unwrap_or(usize::MAX)).collect();if ctx.iter().any(|x|*x>bos){die("context id out of bounds")};let next=p[order+1].parse::<usize>().unwrap_or(vn);let count=p[order+2].parse::<u64>().unwrap_or(0);if next>=vn||count==0{die("invalid transition")};edges.push(Edge{ctx,next,count});}else{die("unknown model record")}}let vocab:Vec<String>=vocab.into_iter().map(|x|x.unwrap_or_else(||die("missing vocabulary token"))).collect();let steps=if a.len()==3{a[2].parse::<usize>().unwrap_or(usize::MAX)}else{20};if steps>10000{die("token count out of range")};let mut ctx=vec![bos;order];let mut out=Vec::new();for _ in 0..steps{let best=edges.iter().filter(|x|x.ctx==ctx).max_by(|x,y|x.count.cmp(&y.count).then_with(||y.next.cmp(&x.next)));let Some(e)=best else{break};if vocab[e.next]=="__BYTEFORGE_EOS__"{break};out.push(vocab[e.next].clone());ctx.rotate_left(1);ctx[order-1]=e.next;}println!("{}",out.join(" "));}
